const deckJs = `"use strict";
(() => {
const api=window.batto,host=document.getElementById("classic-deck-host");if(!api?.invoke||!host)return;let state=null,plugins=[],selectedIndex=-1,selectedAction=null;const $=(s,r=host)=>r.querySelector(s),esc=(v)=>String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");const call=(c,p={})=>api.invoke(c,p);const profile=()=>state?.deck?.profiles?.find(p=>p.id===state.deck.activeProfileId)||state?.deck?.profiles?.[0];const page=()=>{const p=profile();return p?.folders?.find(f=>f.id===p.activeFolderId)||p?.folders?.find(f=>f.id==="root")||p?.folders?.[0]};function sourcePlugin(p){return p?.originalPlugin||p}function actionIcon(a,p){return a?.icon||p?.icon||""}function native(a,p){return !!p?.native&&!p?.originalPlugin}
function markup(){host.innerHTML='<div class="sd-shell"><div class="sd-top"><label>Profil<select id="sd-profile"></select></label><button id="sd-add-profile">+ Profil</button><label>Seite<select id="sd-page"></select></label><button id="sd-add-page">+ Seite</button><label class="small">Zeilen<input id="sd-rows" type="number" min="1" max="10"></label><label class="small">Spalten<input id="sd-cols" type="number" min="1" max="10"></label><button id="sd-grid-apply">Raster</button><button id="sd-plugin-scan">Plugins neu laden</button></div><div class="sd-main"><section class="sd-stage"><div id="sd-grid" class="sd-grid"></div></section><aside class="sd-actions"><div class="sd-actions-head"><h3>Aktionen</h3><span class="sd-note">Originale Pakete zuerst</span></div><input id="sd-search" class="sd-search" placeholder="Aktion oder Plugin suchen"><div id="sd-action-list" class="sd-action-list"></div></aside></div><section id="sd-inspector" class="sd-inspector"></section></div><dialog id="sd-style" class="sd-style-dialog"><form method="dialog"><h3>Taste gestalten</h3><div class="sd-style-grid"><label>Titel<input id="sd-style-title" maxlength="120"></label><label>Untertitel<input id="sd-style-subtitle" maxlength="160"></label><label>Tastenfarbe<input id="sd-style-color" type="color"></label><label>Schriftfarbe<input id="sd-style-text" type="color"></label><label class="wide">Icon / Data-URL<input id="sd-style-icon"></label><label>Ordner<select id="sd-style-folder"></select></label></div><div class="sd-style-actions"><button value="cancel">Abbrechen</button><button id="sd-style-save" value="default" class="primary">Speichern</button></div></form></dialog>';$("#sd-profile").onchange=async e=>{await call("deck:activate-profile",{profileId:e.target.value});selectedIndex=-1;await refresh(false)};$("#sd-page").onchange=async e=>{await call("deck:activate-folder",{profileId:profile().id,folderId:e.target.value});selectedIndex=-1;await refresh(false)};$("#sd-add-profile").onclick=addProfile;$("#sd-add-page").onclick=addPage;$("#sd-grid-apply").onclick=applyGrid;$("#sd-plugin-scan").onclick=()=>refresh(true);$("#sd-search").oninput=renderActions;$("#sd-style-save").onclick=saveStyle}
function render(){const p=profile(),f=page();if(!p||!f)return;$("#sd-profile").innerHTML=state.deck.profiles.map(x=>'<option value="'+esc(x.id)+'" '+(x.id===p.id?'selected':'')+'>'+esc(x.name)+'</option>').join('');$("#sd-page").innerHTML=p.folders.filter(x=>!x.parentId).map(x=>'<option value="'+esc(x.id)+'" '+(x.id===f.id?'selected':'')+'>'+esc(x.name)+'</option>').join('');$("#sd-rows").value=f.rows;$("#sd-cols").value=f.columns;const grid=$("#sd-grid");grid.style.gridTemplateColumns='repeat('+f.columns+',92px)';grid.replaceChildren();for(let i=0;i<f.rows*f.columns;i++){const b=f.buttons?.[i]||{},a=b.actions?.[0],n=document.createElement('button');n.className='sd-key'+(i===selectedIndex?' selected':'');n.type='button';n.dataset.index=i;if(b.color)n.style.background=b.color;if(b.textColor)n.style.color=b.textColor;if(b.icon){const img=document.createElement('img');img.src=b.icon;n.append(img)}const label=document.createElement('span');label.textContent=b.title||a?.title||('Taste '+(i+1));n.append(label);const small=document.createElement('small');small.textContent=String(i+1);n.append(small);const gear=document.createElement('button');gear.type='button';gear.className='gear';gear.textContent='⚙';gear.title='Tastenfarben, Text und Ordner';gear.onclick=e=>{e.stopPropagation();selectedIndex=i;openStyle()};n.append(gear);n.onclick=()=>{selectedIndex=i;render();renderInspector()};n.ondblclick=async()=>{if(!a)return;try{await call('deck:execute-button',{profileId:p.id,folderId:f.id,buttonIndex:i})}catch(e){alert(e.message||e)}};n.ondragover=e=>e.preventDefault();n.ondrop=e=>{e.preventDefault();const data=e.dataTransfer.getData('application/x-batto-action');if(data){selectedIndex=i;selectedAction=JSON.parse(data);applySelectedAction()}};grid.append(n)}renderActions();renderInspector()}
function renderActions(){const q=($("#sd-search")?.value||'').toLowerCase(),root=$("#sd-action-list");if(!root)return;root.replaceChildren();for(const listed of plugins){const p=sourcePlugin(listed),actions=p?.actions||[],matches=actions.filter(a=>!q||String(p.name+' '+a.name+' '+a.id).toLowerCase().includes(q));if(!matches.length)continue;const group=document.createElement('details');group.className='sd-plugin';group.open=q.length>0||plugins.indexOf(listed)<4;const summary=document.createElement('summary');summary.textContent=p.name+(listed.originalPlugin?' · Original':'');group.append(summary);for(const a of matches){const b=document.createElement('button');b.type='button';b.className='sd-action-item '+(listed.originalPlugin||!listed.native?'original':'native');b.draggable=true;const payload={pluginId:p.id,actionId:a.id,name:a.name,icon:actionIcon(a,p),original:!native(a,listed),propertyInspectorPath:a.propertyInspectorPath||p.propertyInspectorPath||'',native:native(a,listed)};b.ondragstart=e=>e.dataTransfer.setData('application/x-batto-action',JSON.stringify(payload));b.onclick=()=>{selectedAction=payload;renderInspector()};if(payload.icon){const img=document.createElement('img');img.src=payload.icon;b.append(img)}const t=document.createElement('div');t.innerHTML='<strong>'+esc(a.name)+'</strong><small>'+(payload.original?(payload.propertyInspectorPath?'Original Property Inspector':'Original-Plugin'):'Native Batto-Aktion')+'</small>';b.append(t);group.append(b)}root.append(group)}}
function button(){return selectedIndex>=0?page()?.buttons?.[selectedIndex]:null}function currentAction(){return button()?.actions?.[0]||null}
function nativeFields(type,a){const s=a?.settings||{},obs=state?.obs||{},scenes=Array.isArray(obs.scenes)?obs.scenes:(obs.scenes?.scenes||[]);if(type==='system.launch')return '<label class="wide">App / Datei<div style="display:flex;gap:6px"><input id="pi-path" value="'+esc(s.path||'')+'"><button id="pi-browse" type="button">…</button></div></label>';if(type==='system.url')return '<label class="wide">Webadresse<input id="pi-url" value="'+esc(s.url||'')+'" placeholder="https://"></label>';if(type==='obs.scene')return '<label>Szene<select id="pi-scene">'+scenes.map(x=>{const name=x.sceneName||x.name||x;return '<option '+(name===s.sceneName?'selected':'')+'>'+esc(name)+'</option>'}).join('')+'</select></label>';if(type==='obs.input.volume')return '<label>Audioquelle<input id="pi-input" value="'+esc(s.inputName||'')+'"></label><label>Lautstärke<input id="pi-volume" type="number" min="0" max="2" step=".05" value="'+esc(s.volumeMul??1)+'"></label>';if(type==='obs.input.mute')return '<label>Audioquelle<input id="pi-input" value="'+esc(s.inputName||'')+'"></label>';return '<div class="sd-note wide">Diese Aktion benötigt keine weiteren Parameter.</div>'}
function renderInspector(){const target=$("#sd-inspector");if(selectedIndex<0){target.innerHTML='<div class="sd-note">Taste auswählen und rechts eine Aktion anklicken oder auf eine Taste ziehen.</div>';return}const b=button()||{},existing=currentAction();let spec=selectedAction;if(!spec&&existing?.type==='streamdeck.original')spec={pluginId:existing.settings?.pluginId,actionId:existing.settings?.actionId,name:existing.title,icon:b.icon,original:true,propertyInspectorPath:existing.settings?.propertyInspectorPath||''};if(!spec&&existing)spec={actionId:existing.type,name:existing.title||existing.type,icon:b.icon,native:true,original:false};const icon=spec?.icon||b.icon||'';let fields='<label class="wide">Titel<input id="pi-title" maxlength="120" value="'+esc(b.title||spec?.name||'')+'"></label>';if(spec?.original)fields+='<div class="wide sd-note">Die Aktion stammt aus dem installierten Original-Stream-Deck-Paket. '+(spec.propertyInspectorPath?'Die Original-HTML-Einstellungen werden verwendet.':'Dieses Paket stellt für diese Aktion keinen HTML-Property-Inspector bereit.')+'</div>';else if(spec)fields+=nativeFields(spec.actionId,existing);target.innerHTML='<div class="sd-inspector-icon">'+(icon?'<img src="'+esc(icon)+'">':'<strong>◫</strong>')+'</div><div class="sd-inspector-fields">'+fields+'</div><div class="sd-inspector-actions"><button id="pi-apply" class="primary">Übernehmen</button>'+(spec?.original&&spec.propertyInspectorPath?'<button id="pi-original">Originale Einstellungen</button>':'')+'<button id="pi-style">⚙ Taste</button><button id="pi-clear">Leeren</button></div>';$("#pi-apply").onclick=applySelectedAction;$("#pi-style").onclick=openStyle;$("#pi-clear").onclick=clearKey;if($("#pi-browse"))$("#pi-browse").onclick=async()=>{$("#pi-path").value=await call('app:choose-path',{title:'App oder Datei auswählen'})};if($("#pi-original"))$("#pi-original").onclick=async()=>{await applySelectedAction();const a=currentAction();await call('streamdeck:open-inspector',{profileId:profile().id,folderId:page().id,buttonIndex:selectedIndex,pluginId:a.settings.pluginId,actionId:a.settings.actionId})}}
async function applySelectedAction(){if(selectedIndex<0)return;const p=profile(),f=page(),old=button()||{},spec=selectedAction||(()=>{const a=currentAction();return a?.type==='streamdeck.original'?{pluginId:a.settings?.pluginId,actionId:a.settings?.actionId,name:a.title,original:true,propertyInspectorPath:a.settings?.propertyInspectorPath}:a?{actionId:a.type,name:a.title,native:true}:null})();if(!spec)return;let action;if(spec.original){const oldA=currentAction();action={id:oldA?.type==='streamdeck.original'?oldA.id:undefined,type:'streamdeck.original',title:spec.name,settings:{pluginId:spec.pluginId,actionId:spec.actionId,propertyInspectorPath:spec.propertyInspectorPath||'',pluginSettings:oldA?.settings?.pluginSettings||{}},delayMs:oldA?.delayMs||0}}else{const type=spec.actionId,s={};if(type==='system.launch')s.path=$("#pi-path")?.value||'';if(type==='system.url')s.url=$("#pi-url")?.value||'';if(type==='obs.scene')s.sceneName=$("#pi-scene")?.value||'';if(type==='obs.input.volume'){s.inputName=$("#pi-input")?.value||'';s.volumeMul=Number($("#pi-volume")?.value)||1}if(type==='obs.input.mute')s.inputName=$("#pi-input")?.value||'';action={type,title:spec.name,settings:s,delayMs:0}}const title=$("#pi-title")?.value||old.title||spec.name;await call('deck:update-button',{profileId:p.id,folderId:f.id,buttonIndex:selectedIndex,button:{...old,title,icon:old.icon||spec.icon||'',actions:[action]}});selectedAction=null;await refresh(false)}
async function clearKey(){if(selectedIndex<0)return;await call('deck:clear-button',{profileId:profile().id,folderId:page().id,buttonIndex:selectedIndex});selectedAction=null;await refresh(false)}function openStyle(){if(selectedIndex<0)return;const b=button()||{},p=profile();$("#sd-style-title").value=b.title||'';$("#sd-style-subtitle").value=b.subtitle||'';$("#sd-style-color").value=b.color||'#152130';$("#sd-style-text").value=b.textColor||'#ffffff';$("#sd-style-icon").value=b.icon||'';$("#sd-style-folder").innerHTML='<option value="">Kein Ordner</option>'+p.folders.filter(f=>f.id!==page().id).map(f=>'<option value="'+esc(f.id)+'" '+(f.id===b.folderId?'selected':'')+'>'+esc(f.name)+'</option>').join('');$("#sd-style").showModal()}async function saveStyle(e){e.preventDefault();const b=button()||{};await call('deck:update-button',{profileId:profile().id,folderId:page().id,buttonIndex:selectedIndex,button:{...b,title:$("#sd-style-title").value,subtitle:$("#sd-style-subtitle").value,color:$("#sd-style-color").value,textColor:$("#sd-style-text").value,icon:$("#sd-style-icon").value,folderId:$("#sd-style-folder").value}});$("#sd-style").close();await refresh(false)}async function addProfile(){const name=prompt('Profilname:','Neues Profil')?.trim();if(name){await call('deck:create-profile',{name});selectedIndex=-1;await refresh(false)}}async function addPage(){const name=prompt('Seitenname:','Neue Seite')?.trim();if(name){await call('deck:create-page',{profileId:profile().id,name});selectedIndex=-1;await refresh(false)}}async function applyGrid(){await call('deck:update-folder',{profileId:profile().id,folderId:page().id,patch:{rows:Number($("#sd-rows").value)||3,columns:Number($("#sd-cols").value)||5}});selectedIndex=-1;await refresh(false)}async function refresh(scan=true){state=await call('state:get');if(scan){const snap=await call('plugins:scan');plugins=snap?.plugins||[]}render()}markup();refresh(true).catch(e=>{host.innerHTML='<div class="panel"><h3>Touch-Deck Fehler</h3><pre>'+esc(e.stack||e.message||e)+'</pre></div>'});
})();`;
