const checks = { main: read("src/main.cjs"), chat: read("src/renderer/multi-chat.js"), tiktok: read("src/services/platforms/tiktok-adapter.cjs"), deck: read("src/renderer/touch-deck-classic.js"), overlay: read("src/stream-overlay/editor.html") };
if (!checks.main.includes('handle("chat:update-settings"')) throw new Error("chat:update-settings fehlt weiter.");
if (checks.chat.includes('id="cfg-twitch-token"')) throw new Error("Twitch OAuth-Feld blieb im Multi-Chat.");
if (!checks.tiktok.includes('mode || "local"')) throw new Error("TikTok Local-Modus fehlt.");
if (!checks.deck.includes('Originale Einstellungen') || checks.deck.includes('Einstellungen als JSON')) throw new Error("Original-Plugin-Einstellungsfluss fehlt.");
if (!checks.overlay.includes('id="field-x"') || !checks.overlay.includes('id="field-z-index"')) throw new Error("Erweiterte Overlay-Einstellungen fehlen.");
console.log("User-Test-Fixes: Chat IPC, TikTok Local-Modus, Original-StreamDeck-Property-Inspector, Touch-Deck-Aktionsbrowser und Overlay-Feineinstellungen eingebaut.");
